import{_ as a,o as l,c as o,ag as r}from"./chunks/framework.D2veAa-g.js";const u=JSON.parse('{"title":"架构师-备考 综合知识-系统基础-操作系统-进程管理","description":"","frontmatter":{"title":"架构师-备考 综合知识-系统基础-操作系统-进程管理"},"headers":[],"relativePath":"综合知识/系统基础/操作系统/进程管理.md","filePath":"综合知识/系统基础/操作系统/进程管理.md","lastUpdated":null}'),n={name:"综合知识/系统基础/操作系统/进程管理.md"};function s(e,t,i,d,h,p){return l(),o("div",null,[...t[0]||(t[0]=[r(`<h2 id="考点清单" tabindex="-1">考点清单 <a class="header-anchor" href="#考点清单" aria-label="Permalink to &quot;考点清单&quot;">​</a></h2><ul><li>[ ] 进程组成与 PCB 组织方式</li><li>[ ] 三态模型与状态转换</li><li>[ ] 进程同步与互斥（临界资源/临界区）</li><li>[ ] 信号量与 PV 操作</li><li>[ ] 信号量值含义与前趋图 PV 规则</li><li>[ ] 生产者-消费者问题</li><li>[ ] 三级调度与调度算法</li><li>[ ] 死锁（必要条件/处理策略/资源计算公式）</li><li>[ ] 线程 vs 进程</li></ul><h2 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h2><h3 id="进程组成与-pcb-组织方式" tabindex="-1">进程组成与 PCB 组织方式 <a class="header-anchor" href="#进程组成与-pcb-组织方式" aria-label="Permalink to &quot;进程组成与 PCB 组织方式&quot;">​</a></h3><blockquote><p>🎯 一句话结论：进程由 <strong>PCB + 程序 + 数据</strong> 三部分组成，是<strong>系统资源分配和调度的基本单位</strong>。</p></blockquote><p><strong>进程组成</strong>：PCB（进程控制块，唯一标识）、程序（描述做什么）、数据（执行所需数据）。</p><p><strong>PCB 组织方式</strong>：</p><table tabindex="0"><thead><tr><th>方式</th><th>说明</th></tr></thead><tbody><tr><td>链接方式</td><td>PCB 通过链表链接，同一状态的 PCB 链接成一个队列</td></tr><tr><td>索引方式</td><td>同状态的 PCB 集中记录在索引表中，通过索引表查找</td></tr><tr><td>顺序方式</td><td>PCB 按顺序连续存放（不适用于动态变化）</td></tr></tbody></table><blockquote><p>⚠️ 三种方式中<strong>索引方式</strong>最常见：为每种进程状态建立索引表，PCB 记录在索引表中。</p></blockquote><h3 id="三态模型" tabindex="-1">三态模型 <a class="header-anchor" href="#三态模型" aria-label="Permalink to &quot;三态模型&quot;">​</a></h3><p><strong>三态模型</strong>（必须熟练掌握转换）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>运行 → 就绪（时间片到）</span></span>
<span class="line"><span>运行 → 阻塞（等待某事件）</span></span>
<span class="line"><span>阻塞 → 就绪（等待的事件发生）</span></span>
<span class="line"><span>就绪 → 运行（被调度）</span></span></code></pre></div><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/fc91e36be89335389d25459e5b84134b_MD5.png" alt="进程三态图"></p><ul><li>三态模型包括：就绪、运行、阻塞。五态模型多了挂起和终止。</li><li>进程基本状态<strong>不包括挂起态</strong>（挂起态是五态模型中的扩展状态）。</li></ul><h3 id="前趋图" tabindex="-1">前趋图 <a class="header-anchor" href="#前趋图" aria-label="Permalink to &quot;前趋图&quot;">​</a></h3><p>详见：<a href="/arch-exam/综合知识/系统基础/操作系统/前趋图与资源图.html">架构师-备考 综合知识-系统基础-操作系统-前趋图与资源图</a></p><h3 id="进程同步与互斥" tabindex="-1">进程同步与互斥 <a class="header-anchor" href="#进程同步与互斥" aria-label="Permalink to &quot;进程同步与互斥&quot;">​</a></h3><ul><li><strong>临界资源</strong>：各进程间需要以互斥方式对其进行访问的资源</li><li><strong>临界区</strong>：进程中<strong>对临界资源实施操作的那段程序</strong></li><li><strong>互斥</strong>：同一时间只能由一个任务单独使用临界资源，使用时加锁（如多进程共享打印机）</li><li><strong>同步</strong>：多个任务可并发执行，有速度差异，需要等待协调。目标是确保进程间正确协作。</li></ul><h3 id="信号量与-pv-操作" tabindex="-1">信号量与 PV 操作 <a class="header-anchor" href="#信号量与-pv-操作" aria-label="Permalink to &quot;信号量与 PV 操作&quot;">​</a></h3><blockquote><p>🎯 一句话结论：互斥信号量初值 = 1；同步信号量初值 = 共享资源数量。P 减一申请，V 加一释放。</p></blockquote><p><strong>信号量</strong>：</p><ul><li>互斥信号量：对临界资源互斥访问，<strong>初值为 1</strong></li><li>同步信号量：对共享资源的访问控制，<strong>初值一般是共享资源的数量</strong></li></ul><p><strong>P/V 操作</strong>：</p><ul><li><strong>P 操作（申请资源）</strong>：S = S - 1，若 S ≥ 0 则继续执行；若 S &lt; 0 则阻塞，插入阻塞队列</li><li><strong>V 操作（释放资源）</strong>：S = S + 1，若 S &gt; 0 则继续执行；若 S ≤ 0 则从阻塞队列唤醒一个进程</li></ul><h3 id="信号量值含义与前趋图-pv-规则" tabindex="-1">信号量值含义与前趋图 PV 规则 <a class="header-anchor" href="#信号量值含义与前趋图-pv-规则" aria-label="Permalink to &quot;信号量值含义与前趋图 PV 规则&quot;">​</a></h3><blockquote><p>🎯 一句话结论：S &lt; 0 时，|S| = 等待进程数。前趋图中信号量数 = 有向边数，初值全 0。</p></blockquote><p><strong>信号量值含义</strong>：</p><ul><li>S ≥ 0：信号量的值表示<strong>可用的资源数</strong></li><li>S &lt; 0：信号量的绝对值 = <strong>等待该资源的进程数</strong></li><li>例：S 初值为 3，当前值为 -1 → 有 <strong>1</strong> 个进程在等待</li></ul><p><strong>前趋图 PV 操作规则</strong>：</p><ul><li>信号量数量 = 前趋图中的<strong>有向边数量</strong></li><li>所有信号量<strong>初值均为 0</strong></li><li>前驱进程完成后执行 <strong>V 操作</strong>（发出信号）</li><li>后继进程开始前执行 <strong>P 操作</strong>（等待信号）</li></ul><h3 id="生产者-消费者问题" tabindex="-1">生产者-消费者问题 <a class="header-anchor" href="#生产者-消费者问题" aria-label="Permalink to &quot;生产者-消费者问题&quot;">​</a></h3><blockquote><p>🎯 一句话结论：三个信号量 — 互斥 S0 + 同步 S1（空闲位）+ 同步 S2（商品数）。</p></blockquote><p><strong>生产者-消费者问题</strong>：三个信号量 — 互斥信号量 S0（仓库使用权，初值 1），同步信号量 S1（空闲位置数），同步信号量 S2（商品个数）。</p><ul><li>⚠️ 不能同时操作缓冲区（即不要求同时操作），但一次只有一个进程操作缓冲区</li><li>⚠️ 不能向满缓冲区存产品，不能从空缓冲区取产品</li></ul><h3 id="进程调度" tabindex="-1">进程调度 <a class="header-anchor" href="#进程调度" aria-label="Permalink to &quot;进程调度&quot;">​</a></h3><p><strong>三级调度</strong>：</p><ul><li>高级调度（作业调度）：决定哪个后备作业调入系统，成为就绪进程。⚠️ <strong>不存在于分时和实时操作系统</strong></li><li>中级调度（对换调度）：决定交换区中哪个就绪进程调入内存</li><li>低级调度（进程调度）：决定内存中哪个就绪进程占用 CPU，最活跃、影响最大。⚠️ <strong>不涉及进程在内存与外存之间交换</strong></li></ul><p><strong>调度算法</strong>：</p><table tabindex="0"><thead><tr><th>算法</th><th>特点</th></tr></thead><tbody><tr><td>先来先服务 FCFS</td><td>先到达先分配 CPU，用于宏观调度</td></tr><tr><td>时间片轮转</td><td>每个进程分配相同时间片轮流使用 CPU，用于微观调度</td></tr><tr><td>优先级调度</td><td>优先级大的先分配 CPU</td></tr><tr><td>多级反馈调度</td><td>时间片轮转 + 优先级结合，多级队列不同优先级和时间片</td></tr></tbody></table><p>调度方式：<strong>可剥夺</strong>（高优先级进程可强行抢占 CPU）vs <strong>不可剥夺</strong>（必须等当前进程自动释放 CPU）。</p><h3 id="死锁" tabindex="-1">死锁 <a class="header-anchor" href="#死锁" aria-label="Permalink to &quot;死锁&quot;">​</a></h3><blockquote><p>🎯 一句话结论：死锁四条件 — 互斥、占有等待、不可剥夺、环路等待。最小资源数 = n × (R-1) + 1。</p></blockquote><p><strong>四个必要条件</strong>：资源互斥、占有并等待、不可剥夺、环路等待。⚠️ &quot;资源共享&quot;不是死锁必要条件。</p><p><strong>处理策略</strong>：</p><ul><li>死锁预防：破坏四个条件之一</li><li>死锁避免：银行家算法，提前计算安全序列，不安全则不分配</li><li>死锁检测：定时运行检测程序</li><li>死锁解除：强制剥夺资源、撤销进程</li></ul><p><strong>死锁资源计算</strong>：n 个进程各需 R 个资源，发生死锁的最大资源数 = n × (R-1)，不发生死锁的最小资源数 = n × (R-1) + 1。</p><h3 id="线程-vs-进程" tabindex="-1">线程 vs 进程 <a class="header-anchor" href="#线程-vs-进程" aria-label="Permalink to &quot;线程 vs 进程&quot;">​</a></h3><blockquote><p>🎯 一句话结论：线程是调度基本单位，进程是资源分配基本单位。同进程线程共享资源，切换开销小。</p></blockquote><p>引入线程原因：进程创建、撤销和切换时空开销大，限制了并发程度。</p><table tabindex="0"><thead><tr><th></th><th>进程</th><th>线程</th></tr></thead><tbody><tr><td>资源</td><td>独立分配资源的单位</td><td>基本不拥有资源（仅 PC、寄存器、栈）</td></tr><tr><td>调度</td><td>传统上可独立调度</td><td><strong>调度和分配的基本单位</strong></td></tr><tr><td>共享</td><td>进程间资源独立</td><td>同进程线程<strong>共享</strong>进程全部资源</td></tr><tr><td>开销</td><td>创建/切换开销大</td><td>创建/切换开销小</td></tr></tbody></table>`,50)])])}const c=a(n,[["render",s]]);export{u as __pageData,c as default};
